// Written with the help of Claude
// AI Usage Note: generated by Claude Code; every row checked against ADR-006, decision 12, by running the tests.
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { priceOf, UNKNOWN_PRICE, wholeHryvnias } from '../../dist/infra/providers/price.js';

describe('wholeHryvnias', () => {
  const rows: { value: unknown; expected: number | undefined; title: string }[] = [
    { value: 450, expected: 450, title: 'keeps a whole number' },
    { value: 0, expected: 0, title: 'keeps 0, a free ticket' },
    { value: 449.5, expected: 450, title: 'rounds half up' },
    { value: 449.49, expected: 449, title: 'rounds down below the half' },
    { value: '450', expected: 450, title: 'reads a string of digits' },
    { value: ' 449.50 ', expected: 450, title: 'reads a string with a decimal point and spaces around it' },
    { value: '449,50', expected: 450, title: 'reads a string with a decimal comma' },
    { value: -1, expected: undefined, title: 'leaves out a negative number' },
    { value: '-5', expected: undefined, title: 'leaves out a negative string' },
    { value: Number.POSITIVE_INFINITY, expected: undefined, title: 'leaves out infinity' },
    { value: Number.NaN, expected: undefined, title: 'leaves out NaN' },
    { value: '1.2.3', expected: undefined, title: 'leaves out a string with two points' },
    { value: '1e3', expected: undefined, title: 'leaves out an exponent' },
    { value: 'від 300', expected: undefined, title: 'leaves out text' },
    { value: '', expected: undefined, title: 'leaves out an empty string' },
    { value: null, expected: undefined, title: 'leaves out null' },
    { value: undefined, expected: undefined, title: 'leaves out a missing value' },
  ];
  for (const { value, expected, title } of rows) {
    test(title, () => {
      assert.equal(wholeHryvnias(value), expected);
    });
  }
});

describe('priceOf', () => {
  const rows: { values: unknown[]; expected: { priceMin: number | null; priceMax: number | null }; title: string }[] = [
    { values: [300, 700], expected: { priceMin: 300, priceMax: 700 }, title: 'gives a range from two prices' },
    { values: [700, 300], expected: { priceMin: 300, priceMax: 700 }, title: 'takes the lower price first' },
    { values: [200, 200], expected: { priceMin: 200, priceMax: null }, title: 'gives one price for two equal ones' },
    { values: [450], expected: { priceMin: 450, priceMax: null }, title: 'gives one price for one value' },
    { values: [0, 0], expected: { priceMin: 0, priceMax: null }, title: 'gives a free event for 0 and 0' },
    { values: [0, 500], expected: { priceMin: 0, priceMax: 500 }, title: 'gives a range from free' },
    { values: [100, 350, 200], expected: { priceMin: 100, priceMax: 350 }, title: 'spans any number of prices' },
    { values: [299.5, 349.4], expected: { priceMin: 300, priceMax: 349 }, title: 'rounds each price' },
    { values: [200.4, 199.6], expected: { priceMin: 200, priceMax: null }, title: 'compares the rounded prices' },
    {
      values: [null, 300],
      expected: { priceMin: 300, priceMax: null },
      title: 'leaves out a value that is not a price',
    },
    { values: [], expected: UNKNOWN_PRICE, title: 'gives an unknown price without values' },
    { values: [null, undefined], expected: UNKNOWN_PRICE, title: 'gives an unknown price, not free, for empty values' },
  ];
  for (const { values, expected, title } of rows) {
    test(title, () => {
      assert.deepEqual(priceOf(values), expected);
    });
  }
});
